"""Layered configuration merge."""
import copy


def _split_key(key):
    if len(key) > 1:
        if key[0] == "+":
            return key[1:], "prepend"
        last = key[-1]
        if last == "+":
            return key[:-1], "append"
        if last == "-":
            return key[:-1], "remove"
        if last == "!":
            return key[:-1], "replace"
        if last == "~":
            return key[:-1], "default"
    return key, "set"


def _need_list(value, what):
    if not isinstance(value, list):
        raise ValueError("%s needs a list" % what)


def merge(base, override):
    out = copy.deepcopy(base)
    for key, value in override.items():
        name, how = _split_key(key)
        if how == "set":
            if value is None:
                out.pop(name, None)
            elif isinstance(value, dict):
                cur = out.get(name)
                out[name] = merge(cur if isinstance(cur, dict) else {}, value)
            else:
                out[name] = copy.deepcopy(value)
        elif how == "replace":
            out[name] = copy.deepcopy(value)
        elif how == "default":
            if name not in out:
                out[name] = copy.deepcopy(value)
        else:
            _need_list(value, key)
            if how == "remove":
                if name not in out:
                    continue
                _need_list(out[name], name)
                out[name] = [x for x in out[name] if x not in value]
                continue
            cur = out.get(name, [])
            _need_list(cur, name)
            out[name] = cur + copy.deepcopy(value) if how == "append" else copy.deepcopy(value) + cur
    return out


def resolve(layers):
    doc = {}
    for layer in layers:
        doc = merge(doc, layer)
    return doc


def flatten(doc, prefix=""):
    out = {}
    for key, value in doc.items():
        path = prefix + key
        if isinstance(value, dict) and value:
            out.update(flatten(value, path + "."))
        else:
            out[path] = value
    return out


def explain(layers):
    doc = {}
    flat = {}
    who = {}
    for i, layer in enumerate(layers):
        doc = merge(doc, layer)
        new = flatten(doc)
        for path, value in new.items():
            if path not in flat or flat[path] != value:
                who[path] = i
        for path in list(who):
            if path not in new:
                del who[path]
        flat = new
    return {path: who[path] for path in sorted(who)}


def lookup(doc, path, default=None):
    cur = doc
    for step in path.split("."):
        if not isinstance(cur, dict) or step not in cur:
            return default
        cur = cur[step]
    return cur

